import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult
from azure.core.credentials import AzureKeyCredential

def extract_and_validate_invoice_data(invoice_document_url: str, required_fields: list[str], min_confidence: float) -> dict:
    """
    Extracts structured data from an invoice document, validates required fields,
    and checks confidence scores using Azure Document Intelligence.

    Args:
        invoice_document_url: The URL to the invoice document (e.g., PDF, JPG, PNG).
        required_fields: A list of field names that must be present and valid.
        min_confidence: The minimum confidence score required for a field to be considered valid.

    Returns:
        A dictionary containing the extracted data, validation status, and any errors.
    """

    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("Please set the AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    try:
        poller = document_intelligence_client.begin_analyze_document(
            "prebuilt-invoice", invoice_document_url
        )
        result: AnalyzeResult = poller.result()
    except Exception as e:
        return {"status": "error", "message": f"Document analysis failed: {str(e)}"}

    extracted_data = {}
    validation_status = {"all_required_fields_present": True, "all_fields_above_min_confidence": True, "missing_fields": [], "low_confidence_fields": {}}

    if result.documents and result.documents[0].fields:
        fields = result.documents[0].fields
        for field_name in required_fields:
            if field_name not in fields:
                validation_status["all_required_fields_present"] = False
                validation_status["missing_fields"].append(field_name)
                extracted_data[field_name] = None
                continue

            field = fields[field_name]
            extracted_value = field.value
            confidence = field.confidence

            if confidence < min_confidence:
                validation_status["all_fields_above_min_confidence"] = False
                validation_status["low_confidence_fields"][field_name] = confidence

            extracted_data[field_name] = {
                "value": extracted_value,
                "confidence": confidence
            }
    else:
        validation_status["all_required_fields_present"] = False
        validation_status["missing_fields"] = required_fields
        validation_status["all_fields_above_min_confidence"] = False # No fields means no confidence.

    return {
        "status": "success",
        "extracted_data": extracted_data,
        "validation_status": validation_status
    }
